import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BQ1gajhD.js";const f=JSON.parse('{"title":"蓝色港湾","description":"","frontmatter":{},"headers":[],"relativePath":"landmarks/blue-harbor.md","filePath":"landmarks/blue-harbor.md","lastUpdated":1787033866000}'),n={name:"landmarks/blue-harbor.md"};function d(o,t,s,i,h,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="蓝色港湾" tabindex="-1">蓝色港湾 <a class="header-anchor" href="#蓝色港湾" aria-label="Permalink to &quot;蓝色港湾&quot;">​</a></h1><p><img src="https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?w=1200" alt="蓝色港湾"></p><blockquote><p>&quot;湖畔的欧式小镇，北京夜景的浪漫之选。&quot;</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>蓝色港湾（Solana）位于北京市朝阳区朝阳公园西北湖畔，是一座融合欧式风情建筑与滨水景观的开放式购物街区。街区以湖为中心，建筑采用地中海风格，喷泉、广场、步道错落有致，白天是休闲购物的欧式小镇，夜晚灯光亮起、水面倒影摇曳，浪漫氛围十足，尤其以冬季的&quot;灯光节&quot;闻名，是北京家庭出游与情侣约会的热门地点。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>开放时间</strong></td><td style="text-align:left;">全天开放（商户10:00-22:00）</td></tr><tr><td style="text-align:left;"><strong>门票价格</strong></td><td style="text-align:left;">免费</td></tr><tr><td style="text-align:left;"><strong>建议游玩</strong></td><td style="text-align:left;">2-3小时</td></tr><tr><td style="text-align:left;"><strong>最佳季节</strong></td><td style="text-align:left;">四季皆宜，秋冬季夜景最佳</td></tr><tr><td style="text-align:left;"><strong>交通方式</strong></td><td style="text-align:left;">地铁14号线枣营站或东风北桥站</td></tr><tr><td style="text-align:left;"><strong>地址</strong></td><td style="text-align:left;">北京市朝阳区朝阳公园路6号</td></tr></tbody></table><h2 id="街区特色" tabindex="-1">街区特色 <a class="header-anchor" href="#街区特色" aria-label="Permalink to &quot;街区特色&quot;">​</a></h2><h3 id="欧式风情建筑" tabindex="-1">欧式风情建筑 <a class="header-anchor" href="#欧式风情建筑" aria-label="Permalink to &quot;欧式风情建筑&quot;">​</a></h3><p>街区内建筑采用地中海、南欧风格，拱门、圆顶、钟楼与喷泉营造出浓郁的异国氛围，是拍照打卡的好地方。</p><h3 id="湖畔景观" tabindex="-1">湖畔景观 <a class="header-anchor" href="#湖畔景观" aria-label="Permalink to &quot;湖畔景观&quot;">​</a></h3><p>蓝色港湾环朝阳公园湖而建，亲水平台与湖边步道相连，白天可看湖景，夜晚水面倒影灯火辉煌。</p><h3 id="灯光节与主题活动" tabindex="-1">灯光节与主题活动 <a class="header-anchor" href="#灯光节与主题活动" aria-label="Permalink to &quot;灯光节与主题活动&quot;">​</a></h3><p>每年冬季举办的&quot;蓝色港湾灯光节&quot;用大量灯光装置装点街区，成为北京冬季最具人气的打卡地标之一。</p><h2 id="游览攻略" tabindex="-1">游览攻略 <a class="header-anchor" href="#游览攻略" aria-label="Permalink to &quot;游览攻略&quot;">​</a></h2><h3 id="推荐路线" tabindex="-1">推荐路线 <a class="header-anchor" href="#推荐路线" aria-label="Permalink to &quot;推荐路线&quot;">​</a></h3><p><strong>半日路线</strong>：</p><p>枣营站 → 街区主广场 → 湖畔步道 → 购物与餐饮 → 夜晚灯光景观</p><h3 id="实用贴士" tabindex="-1">实用贴士 <a class="header-anchor" href="#实用贴士" aria-label="Permalink to &quot;实用贴士&quot;">​</a></h3><ol><li><strong>交通</strong>：地铁14号线枣营站或东风北桥站步行约10分钟</li><li><strong>错峰</strong>：灯光节与节假日人流大，建议错峰或提前前往</li><li><strong>拍照</strong>：傍晚蓝调时刻灯光初亮时最出片</li><li><strong>搭配</strong>：与朝阳公园、三里屯、亮马河串联游玩</li></ol><h3 id="交通方式" tabindex="-1">交通方式 <a class="header-anchor" href="#交通方式" aria-label="Permalink to &quot;交通方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">路线</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>地铁</strong></td><td style="text-align:left;">14号线枣营站或东风北桥站</td></tr><tr><td style="text-align:left;"><strong>公交</strong></td><td style="text-align:left;">朝阳公园周边多路公交</td></tr><tr><td style="text-align:left;"><strong>自驾</strong></td><td style="text-align:left;">定位&quot;蓝色港湾&quot;，有配套停车场</td></tr></tbody></table><h2 id="周边景点" tabindex="-1">周边景点 <a class="header-anchor" href="#周边景点" aria-label="Permalink to &quot;周边景点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">景点</th><th style="text-align:center;">距离</th><th style="text-align:left;">特色</th></tr></thead><tbody><tr><td style="text-align:left;">朝阳公园</td><td style="text-align:center;">步行5分钟</td><td style="text-align:left;">城市大公园</td></tr><tr><td style="text-align:left;">亮马河国际风情水岸</td><td style="text-align:center;">步行15分钟</td><td style="text-align:left;">滨水夜景</td></tr><tr><td style="text-align:left;">三里屯太古里</td><td style="text-align:center;">步行20分钟</td><td style="text-align:left;">潮流时尚街区</td></tr><tr><td style="text-align:left;">北京合生汇</td><td style="text-align:center;">车程15分钟</td><td style="text-align:left;">美食购物中心</td></tr></tbody></table><h2 id="文化意义" tabindex="-1">文化意义 <a class="header-anchor" href="#文化意义" aria-label="Permalink to &quot;文化意义&quot;">​</a></h2><p>蓝色港湾将欧洲小镇的闲适氛围带入城市中心，用滨水景观与光影艺术营造出独特的休闲消费场景，是北京开放式街区与夜经济融合的典范。</p><hr><p><strong>📍 地址</strong>：北京市朝阳区朝阳公园路6号 <strong>🚇 地铁</strong>：14号线枣营站 / 东风北桥站</p><p><strong>💡 Tips</strong>：冬季灯光节是蓝色港湾的招牌，湖畔晚餐+灯光漫步是经典玩法。</p>',29)])])}const b=e(n,[["render",d]]);export{f as __pageData,b as default};
